() => {
  const results = [];
  const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
  cards.forEach((card, idx) => {
    const titleEl = card.querySelector('span');
    const title = titleEl ? titleEl.innerText.trim() : '';
    const link = card.href;
    const rating = card.querySelector('[id*="recipe-star-rating"]')?.getAttribute('data-rating') || 
                   card.querySelector('[id*="recipe-star-rating"]')?.getAttribute('aria-label') || '';
    // Try to find rating text
    const ratingNumEl = card.querySelector('[id*="mntl-recipe-card-meta"]');
    const ratingNum = ratingNumEl ? ratingNumEl.innerText : '';
    results.push({index: idx, title, link, ratingInfo: rating, ratingNum});
  });
  return results;
}"}

